import bisect

class Ring:
    def __init__(self, nodes, vnodes=100):
        self.points = sorted((hash(f"{n}#{i}"), n) for n in nodes for i in range(vnodes))
        self.keys = [p for p, _ in self.points]
    def owner(self, key):
        i = bisect.bisect(self.keys, hash(key)) % len(self.keys)
        return self.points[i][1]

class TTLCache:
    def __init__(self, ttl):
        self.ttl, self.d = ttl, {}
    def get(self, k, now):
        v = self.d.get(k)
        return v[0] if v and now < v[1] else None
    def set(self, k, v, now):
        self.d[k] = (v, now + self.ttl)

